    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)

    # Complete the outer rectangular frame defined by the extreme points.
    for c in range(cmin, cmax + 1):
        if grid[rmin][c] == background:
            out[rmin][c] = 2
        if grid[rmax][c] == background:
            out[rmax][c] = 2
    for r in range(rmin, rmax + 1):
        if grid[r][cmin] == background:
            out[r][cmin] = 2
        if grid[r][cmax] == background:
            out[r][cmax] = 2

    # Connect aligned foreground points along their rows and columns.
    for r in range(len(grid)):
